<template><div class="page"><div class="section-title"><div><div class="eyebrow">BACKGROUND OPERATIONS</div><h2>后台任务</h2><span class="muted">自动监听、故障分级、保守修复与人工接力</span></div><n-button type="primary" @click="load">刷新任务</n-button></div><div class="metric-grid" style="grid-template-columns:repeat(4,1fr)"><div class="metric"><div><div class="metric-value">{{tasks.length}}</div><div class="metric-label">全部任务</div></div></div><div class="metric"><div><div class="metric-value">{{tasks.filter(x=>x.severity==='simple').length}}</div><div class="metric-label">自动修复候选</div></div></div><div class="metric"><div><div class="metric-value">{{tasks.filter(x=>x.incident_id).length}}</div><div class="metric-label">已转故障报告</div></div></div><div class="metric"><div><div class="metric-value">{{tasks.filter(x=>x.status==='resolved').length}}</div><div class="metric-label">已恢复</div></div></div></div><div class="panel"><n-data-table :columns="columns" :data="tasks" :loading="loading" :pagination="{pageSize:10}"/></div></div></template>
<script setup>import{h,ref,onMounted}from'vue';import{useRouter}from'vue-router';import{backgroundApi}from'@/api';const router=useRouter(),tasks=ref([]),loading=ref(false);const severityLabel=s=>({simple:'简单',severe:'严重',unknown:'未知',critical:'严重',warning:'告警'}[s]||s||'未知'),severityType=s=>s==='simple'?'success':(s==='severe'||s==='critical'?'error':s==='warning'?'warning':'default'),statusLabel=s=>({received:'已接收',collecting_evidence:'采集证据中',analyzing:'分析中',policy_evaluating:'策略评估',auto_repair_pending:'等待自动修复',auto_repairing:'自动修复中',waiting_verification:'验证恢复中',resolved:'已恢复',incident_created:'已生成故障报告',waiting_human:'等待人工介入',failed:'处理失败',cancelled:'已取消'}[s]||s);const columns=[{title:'告警',key:'alert_name'},{title:'级别',key:'severity',render:r=>h('n-tag',{type:severityType(r.severity),size:'small'},()=>severityLabel(r.severity))},{title:'处理状态',key:'status',render:r=>statusLabel(r.status)},{title:'目标 Pod',key:'target_pod',render:r=>r.target_pod||'—'},{title:'处置结果',key:'repair_result',render:r=>r.repair_result||r.severity_reason||'等待分析'},{title:'创建时间',key:'created_at',render:r=>new Date(r.created_at).toLocaleString()},{title:'操作',key:'action',render:r=>r.incident_id?h('button',{class:'link-button',onClick:()=>router.push(`/app/incidents/${r.incident_id}`)},'查看故障报告'):''}];async function load(){loading.value=true;try{tasks.value=(await backgroundApi.list()).tasks||[]}finally{loading.value=false}}onMounted(load)</script>
